// Local-only photographs of the production pavilion for its visitor plan.
const wait=ms=>new Promise(resolve=>setTimeout(resolve,ms));
export async function captureMuseumPlan(museum,area,dark){
  try{
    const fullScreen=['building','orientation','hall-front','hall-across'].includes(area);
    const style=document.createElement('style');
    style.textContent=fullScreen ? '.museum-orientation-hint{visibility:hidden!important}' : '.view-museum .museum-header,.view-museum .museum-footer,.view-museum .museum-welcome,.view-museum .museum-walk,.museum-orientation-hint{visibility:hidden!important}';
    style.textContent += '.exhibition-ticket{display:none!important}';
    document.head.append(style);
    await museum.awaitInitialCollection();
    const selected=museum.collection.find(view=>view.id==='PNZPdB__yBeyYjkF')||museum.collection[0];
    if(fullScreen&&!selected)throw new Error('The public collection must load before capturing the Gallery.');
    if(selected)museum.selected=selected;
    await Promise.all([museum.warmMuseumImages(),museum._scene.setExhibition(selected),museum.syncWall(),museum._scene.prepareArchive()]);
    museum.dark=dark;museum._scene.setTheme(dark);
    if(fullScreen){
      // Preserve the actual visitor interface and production camera poses.
      museum.area='hall';museum.panelOpen=false;
      museum.hallAngle=area==='hall-front'?'front':'across';
      await museum._scene.setHallAngle(museum.hallAngle,{instant:true});
      if(area==='building')await museum.visit('about');
      else if(area==='orientation')museum.openInfo('control');
      await museum.$nextTick();
      await document.fonts.ready;
      await wait(2400);
      document.documentElement.dataset.planCapture='ready';
      return;
    }
    museum.area=area;museum.panelOpen=false;
    await museum._scene.setHallAngle('front',{instant:true});
    await museum._scene.go(area,{instant:true});
    museum.panelOpen=['directory','compose','archive'].includes(area);
    await museum.$nextTick();
    // Use the station's exact visitor camera. The model is the one exception
    // because selecting it takes the live camera outside the building.
    if(area==='about'){
      const pose=museum._scene.snapshotPose();
      const eye=[8.13,1.75,3.585];
      const target=[6.7,1.75,-1.2];
      const [dx,dy,dz]=target.map((value,index)=>value-eye[index]);
      await museum._scene.restorePose({...pose,area:'hall',position:eye,look:{yaw:Math.atan2(-dx,-dz),pitch:Math.atan2(dy,Math.hypot(dx,dz))},fov:46,offset:0});
    }
    await wait(2400);
    document.documentElement.dataset.planCapture='ready';
  }catch(error){document.documentElement.dataset.planCapture='error';document.documentElement.dataset.planError=error.message;}
}
